package zw.co.hyperfeeds.commerce;

import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.http.*; import org.springframework.jdbc.core.simple.JdbcClient; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import java.math.*; import java.util.*;

@RestController @RequestMapping("/commerce")
public class CommerceController {
 private static final Logger log=LoggerFactory.getLogger(CommerceController.class);
 private final JdbcClient jdbc; private final PaymentGateway gateway; public CommerceController(JdbcClient jdbc,PaymentGateway gateway){this.jdbc=jdbc;this.gateway=gateway;}
 @PutMapping("/cart/items/{productId}") @Transactional public void item(Authentication a,@PathVariable UUID productId,@Valid @RequestBody ItemRequest r){UUID user=zw.co.hyperfeeds.identity.CurrentUser.id(a);UUID cart=jdbc.sql("select id from carts where user_id=:u and status='ACTIVE'").param("u",user).query(UUID.class).optional().orElseGet(()->{UUID id=UUID.randomUUID();jdbc.sql("insert into carts(id,user_id,branch_id) values(:id,:u,:b)").param("id",id).param("u",user).param("b",r.branchId).update();return id;});UUID actual=jdbc.sql("select branch_id from carts where id=:id").param("id",cart).query(UUID.class).single();if(!actual.equals(r.branchId))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cart belongs to another branch");jdbc.sql("insert into cart_items(cart_id,product_id,quantity) values(:c,:p,:q) on conflict(cart_id,product_id) do update set quantity=excluded.quantity").param("c",cart).param("p",productId).param("q",r.quantity).update();}
 @DeleteMapping("/cart/items/{productId}") public void remove(Authentication a,@PathVariable UUID productId){jdbc.sql("delete from cart_items where product_id=:p and cart_id in(select id from carts where user_id=:u and status='ACTIVE')").param("p",productId).param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).update();}
 @GetMapping("/cart") public List<Map<String,Object>> cart(Authentication a){return jdbc.sql("select ci.product_id,p.name,ci.quantity,bp.amount unit_price,ci.quantity*bp.amount line_total,c.branch_id from carts c join cart_items ci on ci.cart_id=c.id join products p on p.id=ci.product_id left join branch_prices bp on bp.product_id=p.id and bp.branch_id=c.branch_id and bp.effective_to is null where c.user_id=:u and c.status='ACTIVE'").param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).query().listOfRows();}
 @PostMapping("/checkout") @Transactional @ResponseStatus(HttpStatus.CREATED) public Checkout checkout(Authentication a){UUID user=zw.co.hyperfeeds.identity.CurrentUser.id(a);log.info("CHECKOUT_START userId={}",user);Map<String,Object> cart=jdbc.sql("select c.id,c.branch_id,u.phone_number from carts c join users u on u.id=c.user_id where c.user_id=:u and c.status='ACTIVE'").param("u",user).query().singleRow();UUID cartId=(UUID)cart.get("id"),branch=(UUID)cart.get("branch_id");List<Map<String,Object>> lines=jdbc.sql("select ci.product_id,p.name,ci.quantity,bp.amount,bp.currency from cart_items ci join products p on p.id=ci.product_id join branch_prices bp on bp.product_id=p.id and bp.branch_id=:b and bp.effective_to is null where ci.cart_id=:c").param("b",branch).param("c",cartId).query().listOfRows();log.info("CHECKOUT_CART_LOADED userId={} cartId={} branchId={} lineCount={}",user,cartId,branch,lines.size());if(lines.isEmpty()){log.warn("CHECKOUT_REJECTED userId={} cartId={} reason=empty_or_unpriced",user,cartId);throw new ResponseStatusException(HttpStatus.CONFLICT,"Cart is empty or contains unpriced products");}BigDecimal total=BigDecimal.ZERO;String currency=null;for(var line:lines){UUID product=(UUID)line.get("product_id");BigDecimal qty=(BigDecimal)line.get("quantity"),price=(BigDecimal)line.get("amount");String cur=((String)line.get("currency")).trim();if(currency!=null&&!currency.equals(cur)){log.warn("CHECKOUT_REJECTED userId={} cartId={} reason=mixed_currencies",user,cartId);throw new ResponseStatusException(HttpStatus.CONFLICT,"Cart has mixed currencies");}currency=cur;int changed=jdbc.sql("update branch_inventory set reserved=reserved+:q,version=version+1 where branch_id=:b and product_id=:p and on_hand-reserved>=:q").param("q",qty).param("b",branch).param("p",product).update();if(changed==0){log.warn("CHECKOUT_REJECTED userId={} cartId={} productId={} reason=insufficient_inventory",user,cartId,product);throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient inventory for "+line.get("name"));}log.debug("CHECKOUT_INVENTORY_RESERVED cartId={} productId={} quantity={}",cartId,product,qty);total=total.add(qty.multiply(price));}UUID order=UUID.randomUUID();String ref="ORD-"+order.toString().substring(0,8).toUpperCase();log.info("CHECKOUT_ORDER_CREATING orderId={} orderReference={} total={} currency={} lineCount={}",order,ref,total,currency,lines.size());jdbc.sql("insert into orders(id,reference,user_id,branch_id,status,total,currency) values(:id,:ref,:u,:b,'PAYMENT_PENDING',:total,:currency)").param("id",order).param("ref",ref).param("u",user).param("b",branch).param("total",total).param("currency",currency).update();for(var line:lines){BigDecimal qty=(BigDecimal)line.get("quantity"),price=(BigDecimal)line.get("amount");jdbc.sql("insert into order_items(order_id,product_id,product_name,quantity,unit_price,line_total) values(:o,:p,:n,:q,:price,:line)").param("o",order).param("p",line.get("product_id")).param("n",line.get("name")).param("q",qty).param("price",price).param("line",qty.multiply(price)).update();}log.info("CHECKOUT_PAYNOW_START orderId={} orderReference={} total={} currency={} customerPhone={}",order,ref,total,currency,PaynowPaymentGateway.maskPhone((String)cart.get("phone_number")));PaymentGateway.Payment payment=gateway.start(ref,total,currency,(String)cart.get("phone_number"));log.info("CHECKOUT_PAYNOW_INITIATED orderId={} orderReference={} providerReference={} pollUrlReceived={}",order,ref,payment.reference(),payment.pollUrl()!=null&&!payment.pollUrl().isBlank());jdbc.sql("insert into payments(order_id,provider,provider_reference,status,poll_url,instructions,amount,currency) values(:o,'PAYNOW',:ref,'SENT_TO_SUBSCRIBER',:poll,:instructions,:amount,:currency)").param("o",order).param("ref",payment.reference()).param("poll",payment.pollUrl()).param("instructions",payment.instructions()).param("amount",total).param("currency",currency).update();jdbc.sql("update carts set status='CHECKED_OUT',updated_at=now() where id=:id").param("id",cartId).update();log.info("CHECKOUT_COMPLETE userId={} cartId={} orderId={} orderReference={} providerReference={}",user,cartId,order,ref,payment.reference());return new Checkout(order,ref,total,currency,payment.reference(),payment.instructions());}
 @GetMapping("/orders") public List<Map<String,Object>> orders(Authentication a){return jdbc.sql("select id,reference,branch_id,status,total,currency,created_at from orders where user_id=:u order by created_at desc").param("u",zw.co.hyperfeeds.identity.CurrentUser.id(a)).query().listOfRows();}
 public record ItemRequest(@NotNull UUID branchId,@NotNull @DecimalMin("0.001") BigDecimal quantity){} public record Checkout(UUID orderId,String reference,BigDecimal total,String currency,String paynowReference,String instructions){}
}
